#!/usr/bin/env node
// Turns the design system tokens (design/tokens.json, exported from the Corazones design system)
// into src/theme/tokens.ts. Run `npm run theme` after replacing design/tokens.json; a test fails
// when the generated file is out of date.
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');

// Poppins ships one font file per weight, so React Native picks the weight through the family name.
const FAMILY_BY_WEIGHT = {
  400: 'Poppins_400Regular',
  500: 'Poppins_500Medium',
  600: 'Poppins_600SemiBold',
  700: 'Poppins_700Bold',
};

const camel = (name) => name.replace(/-([a-z0-9])/g, (_, char) => char.toUpperCase());

const px = (value) => parseFloat(String(value));

function hex(r, g, b) {
  return '#' + [r, g, b].map((channel) => Number(channel).toString(16).padStart(2, '0')).join('');
}

// "0 8px 18px rgba(255, 45, 122, 0.30)" -> React Native shadow props.
function toShadow(css) {
  const match = css.match(
    /^(-?[\d.]+)(?:px)?\s+(-?[\d.]+)(?:px)?\s+([\d.]+)(?:px)?\s+rgba?\(\s*(\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\s*\)$/
  );
  if (!match) {
    throw new Error(`Unsupported shadow value: ${css}`);
  }
  const [, x, y, blur, r, g, b, alpha = '1'] = match;
  return {
    shadowColor: hex(r, g, b),
    shadowOffset: { width: Number(x), height: Number(y) },
    shadowOpacity: Number(alpha),
    shadowRadius: Number(blur) / 2,
    elevation: Math.round(Number(blur) / 2),
  };
}

function resolveColors(colorTokens, themeId, firstThemeId) {
  const raw = {};
  for (const token of colorTokens) {
    const value =
      typeof token.value === 'string'
        ? token.value
        : (token.value[themeId] ?? token.value[firstThemeId]);
    raw[token.name] = value;
  }

  const resolve = (name, seen = []) => {
    const value = raw[name];
    const alias = value.match(/^\{(.+)\}$/);
    if (!alias) {
      return value;
    }
    if (seen.includes(name) || !(alias[1] in raw)) {
      throw new Error(`Bad color alias "${value}" in token "${name}"`);
    }
    return resolve(alias[1], [...seen, name]);
  };

  return Object.fromEntries(Object.keys(raw).map((name) => [camel(name), resolve(name)]));
}

function scale(tokens, prefix) {
  return Object.fromEntries(
    tokens.map((token) => [camel(token.name.replace(prefix, '')), px(token.value)])
  );
}

function generate(tokens) {
  const themeIds = tokens.color.themes.map((theme) => theme.id);
  const firstThemeId = themeIds[0];

  const themes = Object.fromEntries(
    themeIds.map((id) => [
      id,
      {
        colors: resolveColors(tokens.color.tokens, id, firstThemeId),
        shadow: Object.fromEntries(
          tokens.shadow.tokens.map((token) => [
            camel(token.name.replace('shadow-', '')),
            toShadow(typeof token.value === 'string' ? token.value : (token.value[id] ?? token.value[firstThemeId])),
          ])
        ),
      },
    ])
  );

  const typography = {};
  for (const group of tokens.type.groups) {
    for (const style of group.styles) {
      const fontSize = px(style.fontSize);
      const entry = {
        fontFamily: FAMILY_BY_WEIGHT[style.fontWeight],
        fontSize,
        lineHeight: px(style.lineHeight),
      };
      if (style.letterSpacing) {
        entry.letterSpacing = Number((parseFloat(style.letterSpacing) * fontSize).toFixed(4));
      }
      typography[camel(style.name)] = entry;
    }
  }

  const body = {
    themes,
    spacing: scale(tokens.spacing.tokens, 'space-'),
    radius: scale(tokens.radius.tokens, 'radius-'),
    size: scale(tokens.size.tokens, ''),
    opacity: scale(tokens.opacity.tokens, 'opacity-'),
    typography,
  };

  const lines = [
    '// GENERATED by scripts/generate-theme.js from design/tokens.json. Do not edit by hand:',
    '// replace design/tokens.json and run `npm run theme`.',
  ];
  for (const [name, value] of Object.entries(body)) {
    lines.push('', `export const ${name} = ${JSON.stringify(value, null, 2)} as const;`);
  }
  lines.push('', 'export type ThemeName = keyof typeof themes;', '');
  return lines.join('\n');
}

module.exports = { generate };

if (require.main === module) {
  const tokens = JSON.parse(fs.readFileSync(path.join(root, 'design/tokens.json'), 'utf8'));
  fs.writeFileSync(path.join(root, 'src/theme/tokens.ts'), generate(tokens));
  console.log('Generated src/theme/tokens.ts');
}
